<?php
/**
 * generate-image-pack.php — builds the plugin's built-in image pack.
 *
 * Original artwork generated by scripts/generate-image-pack.php, © JHMG, released under GPL-2.0-or-later.
 *
 * Usage: php scripts/generate-image-pack.php [outDir]   (default: wp-plugin/assets/images)
 *
 * Writes every SVG, manifest.json and README.txt into outDir. Dev-only: this
 * script is not shipped in the plugin zip. It is fully deterministic — every
 * "random" variation comes from a fixed integer seed per image fed into a small
 * integer LCG, and every computed coordinate is rounded to one decimal and
 * formatted identically — so a fresh run reproduces the committed files byte
 * for byte (tests/ImagePackTest.php checks this). Standard library only.
 */

declare(strict_types=1);

// ---------------------------------------------------------------------------
// Primitives
// ---------------------------------------------------------------------------

/** Deterministic 31-bit LCG (identical on every 64-bit PHP build). */
final class Rng
{
    private int $s;

    public function __construct(int $seed)
    {
        $this->s = ($seed & 0x7fffffff) ?: 1;
    }

    public function next(): float
    {
        $this->s = ($this->s * 1103515245 + 12345) & 0x7fffffff;

        return ($this->s >> 4) / 134217728; // drop the weak low bits
    }

    public function range(float $a, float $b): float
    {
        return $a + ($b - $a) * $this->next();
    }

    public function int(int $a, int $b): int
    {
        return min($b, $a + (int) floor($this->next() * ($b - $a + 1)));
    }
}

/** Format a number: one decimal, no trailing ".0", never "-0". */
function f(float|int $v): string
{
    $r = round((float) $v, 1);
    $s = number_format($r, 1, '.', '');
    if (str_ends_with($s, '.0')) {
        $s = substr($s, 0, -2);
    }

    return $s === '-0' ? '0' : $s;
}

/** Build an element. Floats are formatted with f(); strings are XML-escaped. */
function el(string $name, array $a = [], ?string $inner = null): string
{
    $s = '<' . $name;
    foreach ($a as $k => $v) {
        if ($v === null) {
            continue;
        }
        $s .= ' ' . $k . '="' . (is_float($v) ? f($v) : htmlspecialchars((string) $v, ENT_XML1 | ENT_QUOTES, 'UTF-8')) . '"';
    }

    return $inner === null ? $s . '/>' : $s . '>' . $inner . '</' . $name . '>';
}

/** @param list<array{0:float|int,1:string,2?:float|int}> $stops */
function stops(array $stops): string
{
    $o = '';
    foreach ($stops as $st) {
        $o .= el('stop', ['offset' => (float) $st[0], 'stop-color' => $st[1], 'stop-opacity' => isset($st[2]) ? (float) $st[2] : null]);
    }

    return $o;
}

function lin(string $id, array $stops, float $x1 = 0, float $y1 = 0, float $x2 = 0, float $y2 = 1, array $extra = []): string
{
    return el('linearGradient', ['id' => $id, 'x1' => $x1, 'y1' => $y1, 'x2' => $x2, 'y2' => $y2] + $extra, stops($stops));
}

function rad(string $id, array $stops, array $extra = []): string
{
    return el('radialGradient', ['id' => $id] + $extra, stops($stops));
}

/** A soft glow: radial gradient from colour at opacity $op to transparent. */
function glowDef(string $id, string $color, float $op): string
{
    return rad($id, [[0, $color, $op], [0.55, $color, $op * 0.45], [1, $color, 0]]);
}

function blurDef(string $id, float $std): string
{
    return el('filter', ['id' => $id, 'x' => '-50%', 'y' => '-50%', 'width' => '200%', 'height' => '200%'], el('feGaussianBlur', ['stdDeviation' => $std]));
}

function shadowDef(string $id, string $color, float $op, float $dy = 18, float $std = 22): string
{
    // userSpaceOnUse region = the whole canvas, so blurred shadows of small shapes are never clipped into boxes.
    return el('filter', ['id' => $id, 'filterUnits' => 'userSpaceOnUse', 'x' => '-10%', 'y' => '-10%', 'width' => '120%', 'height' => '130%'],
        el('feDropShadow', ['dx' => 0, 'dy' => $dy, 'stdDeviation' => $std, 'flood-color' => $color, 'flood-opacity' => $op]));
}

/**
 * Smooth path through points (Catmull-Rom converted to cubic Béziers).
 * @param list<array{0:float,1:float}> $p
 */
function smooth(array $p, bool $closed = false): string
{
    $n = count($p);
    $get = static function (int $i) use ($p, $n, $closed): array {
        if ($closed) {
            return $p[(($i % $n) + $n) % $n];
        }

        return $p[max(0, min($n - 1, $i))];
    };
    $d    = 'M' . f($p[0][0]) . ' ' . f($p[0][1]);
    $last = $closed ? $n : $n - 1;
    for ($i = 0; $i < $last; $i++) {
        $p0 = $get($i - 1);
        $p1 = $get($i);
        $p2 = $get($i + 1);
        $p3 = $get($i + 2);
        $c1 = [$p1[0] + ($p2[0] - $p0[0]) / 6, $p1[1] + ($p2[1] - $p0[1]) / 6];
        $c2 = [$p2[0] - ($p3[0] - $p1[0]) / 6, $p2[1] - ($p3[1] - $p1[1]) / 6];
        $d .= 'C' . f($c1[0]) . ' ' . f($c1[1]) . ' ' . f($c2[0]) . ' ' . f($c2[1]) . ' ' . f($p2[0]) . ' ' . f($p2[1]);
    }

    return $closed ? $d . 'Z' : $d;
}

/** Points of a horizontal wave across [x0,x1]. */
function wavePoints(float $x0, float $x1, float $y, float $amp, float $len, float $phase, int $steps = 12, float $amp2 = 0, float $len2 = 1): array
{
    $pts = [];
    for ($i = 0; $i <= $steps; $i++) {
        $x     = $x0 + ($x1 - $x0) * $i / $steps;
        $pts[] = [$x, $y + $amp * sin($x / $len * 2 * M_PI + $phase) + $amp2 * sin($x / $len2 * 2 * M_PI + $phase * 1.7)];
    }

    return $pts;
}

/** Filled wave area from a wave line down to $bottom. */
function waveArea(array $pts, float $bottom): string
{
    $first = $pts[0];
    $last  = $pts[count($pts) - 1];

    return smooth($pts) . 'L' . f($last[0]) . ' ' . f($bottom) . 'L' . f($first[0]) . ' ' . f($bottom) . 'Z';
}

/** Organic closed blob. */
function blob(Rng $r, float $cx, float $cy, float $rad, int $n = 7, float $wobble = 0.22, float $sy = 1.0): string
{
    $pts = [];
    for ($i = 0; $i < $n; $i++) {
        $a     = 2 * M_PI * $i / $n;
        $rr    = $rad * (1 + $r->range(-$wobble, $wobble));
        $pts[] = [$cx + $rr * cos($a), $cy + $rr * sin($a) * $sy];
    }

    return smooth($pts, true);
}

/** Four-point sparkle centred on (x,y). */
function sparkle(float $x, float $y, float $s, string $fill, float $op = 1.0): string
{
    $k = $s * 0.22;
    $d = 'M' . f($x) . ' ' . f($y - $s) . 'Q' . f($x + $k) . ' ' . f($y - $k) . ' ' . f($x + $s) . ' ' . f($y)
        . 'Q' . f($x + $k) . ' ' . f($y + $k) . ' ' . f($x) . ' ' . f($y + $s)
        . 'Q' . f($x - $k) . ' ' . f($y + $k) . ' ' . f($x - $s) . ' ' . f($y)
        . 'Q' . f($x - $k) . ' ' . f($y - $k) . ' ' . f($x) . ' ' . f($y - $s) . 'Z';

    return el('path', ['d' => $d, 'fill' => $fill, 'opacity' => $op < 1 ? $op : null]);
}

function plus(float $x, float $y, float $s, string $stroke, float $w = 6, float $op = 1.0): string
{
    return el('path', ['d' => 'M' . f($x - $s) . ' ' . f($y) . 'H' . f($x + $s) . 'M' . f($x) . ' ' . f($y - $s) . 'V' . f($y + $s),
        'stroke' => $stroke, 'stroke-width' => $w, 'stroke-linecap' => 'round', 'opacity' => $op < 1 ? $op : null]);
}

function rr(float $x, float $y, float $w, float $h, float $r, string $fill, array $extra = []): string
{
    return el('rect', ['x' => $x, 'y' => $y, 'width' => $w, 'height' => $h, 'rx' => $r, 'fill' => $fill] + $extra);
}

function circ(float $cx, float $cy, float $r, string $fill, array $extra = []): string
{
    return el('circle', ['cx' => $cx, 'cy' => $cy, 'r' => $r, 'fill' => $fill] + $extra);
}

/** Dot grid as individual circles inside a box (used for small decorative grids). */
function dotGrid(float $x, float $y, int $cols, int $rows, float $gap, float $r, string $fill, float $op): string
{
    $o = '';
    for ($j = 0; $j < $rows; $j++) {
        for ($i = 0; $i < $cols; $i++) {
            $o .= circ($x + $i * $gap, $y + $j * $gap, $r, $fill);
        }
    }

    return el('g', ['opacity' => $op], $o);
}

function svg(int $w, int $h, string $title, string $defs, string $body): string
{
    return '<svg xmlns="http://www.w3.org/2000/svg" width="' . $w . '" height="' . $h . '" viewBox="0 0 ' . $w . ' ' . $h . '" role="img">' . "\n"
        . el('title', [], htmlspecialchars($title, ENT_XML1, 'UTF-8')) . "\n"
        . ($defs !== '' ? '<defs>' . $defs . '</defs>' . "\n" : '')
        . $body . "\n"
        . '</svg>' . "\n";
}

