// ---------------------------------------------------------------------------
// HERO (1600×900) — dark, rich backgrounds; white text stays readable.
// ---------------------------------------------------------------------------

function heroBase(array $c, string $from, string $to, string $mid = ''): string
{
    $st = $mid === '' ? [[0, $from], [1, $to]] : [[0, $from], [0.55, $mid], [1, $to]];

    return lin('bg', $st, 0, 0, 1, 1);
}

/** Darkening scrim on the left/centre so overlaid white text keeps contrast. */
function scrimDef(string $color, float $op): string
{
    return rad('scrim', [[0, $color, $op], [1, $color, 0]], ['cx' => '.38', 'cy' => '.45', 'r' => '.6']);
}

function hero_blue(Rng $r): array
{
    $c    = PAL['blue'];
    $defs = heroBase($c, $c['950'], $c['700'], $c['900'])
        . glowDef('g1', $c['500'], 0.7) . glowDef('g2', $c['acc'], 0.45) . glowDef('g3', '#6366f1', 0.6)
        . lin('w1', [[0, $c['400'], 0.0], [0.5, $c['300'], 0.35], [1, $c['acc'], 0.15]], 0, 0, 1, 0)
        . lin('w2', [[0, $c['600'], 0.5], [1, $c['acc'], 0.35]], 0, 0, 1, 0)
        . lin('w3', [[0, $c['800'], 0.9], [1, $c['600'], 0.8]], 0, 0, 1, 0)
        . scrimDef($c['950'], 0.45);
    $b = rr(0, 0, 1600, 900, 0, 'url(#bg)')
        . circ(1350, 120, 720, 'url(#g1)') . circ(150, 820, 620, 'url(#g3)') . circ(1150, 820, 520, 'url(#g2)');
    // Flowing hairlines.
    $lines = '';
    for ($k = 0; $k < 18; $k++) {
        $pts    = wavePoints(-40, 1640, 520 + $k * 9, 70 + $k * 2, 1500, 0.6 + $k * 0.06, 14, 20, 640);
        $lines .= el('path', ['d' => smooth($pts)]);
    }
    $b .= el('g', ['fill' => 'none', 'stroke' => '#ffffff', 'stroke-opacity' => '.10', 'stroke-width' => 1.5], $lines);
    $b .= el('path', ['d' => waveArea(wavePoints(-40, 1640, 690, 50, 1300, 2.1, 12), 900), 'fill' => 'url(#w1)']);
    $b .= el('path', ['d' => waveArea(wavePoints(-40, 1640, 750, 44, 1100, 3.4, 12), 900), 'fill' => 'url(#w2)']);
    $b .= el('path', ['d' => waveArea(wavePoints(-40, 1640, 812, 30, 900, 0.8, 12), 900), 'fill' => 'url(#w3)']);
    $b .= rr(0, 0, 1600, 900, 0, 'url(#scrim)');
    $b .= dotGrid(1240, 120, 8, 5, 26, 2.2, '#ffffff', 0.18);
    $b .= sparkle(1180, 300, 14, '#ffffff', 0.7) . sparkle(260, 170, 9, '#ffffff', 0.5);

    return [$defs, $b];
}

function hero_purple(Rng $r): array
{
    $c    = PAL['purple'];
    $defs = heroBase($c, $c['950'], $c['800'], $c['900'])
        . glowDef('g1', $c['600'], 0.75) . glowDef('g2', $c['acc'], 0.45) . glowDef('g3', $c['acc2'], 0.3)
        . lin('rb', [[0, $c['acc'], 0], [0.35, $c['acc'], 0.55], [0.7, $c['400'], 0.5], [1, $c['acc2'], 0]], 0, 0, 1600, 0, ['gradientUnits' => 'userSpaceOnUse'])
        . blurDef('bl', 40) . scrimDef($c['950'], 0.4);
    $b = rr(0, 0, 1600, 900, 0, 'url(#bg)')
        . circ(1250, 300, 700, 'url(#g1)') . circ(300, 900, 500, 'url(#g2)') . circ(1500, 850, 400, 'url(#g3)');
    // Aurora: a blurred band plus a ribbon of fine lines.
    $band = wavePoints(-100, 1700, 470, 140, 1700, 4.0, 10, 30, 700);
    $b .= el('path', ['d' => smooth($band), 'fill' => 'none', 'stroke' => 'url(#rb)', 'stroke-width' => 120, 'filter' => 'url(#bl)', 'opacity' => '.8']);
    $lines = '';
    for ($k = 0; $k < 26; $k++) {
        $pts    = wavePoints(-60, 1660, 400 + $k * 6, 140 - $k * 1.5, 1700, 4.0 + $k * 0.035, 16, 30, 700);
        $lines .= el('path', ['d' => smooth($pts)]);
    }
    $b .= el('g', ['fill' => 'none', 'stroke' => 'url(#rb)', 'stroke-width' => 1.4], $lines);
    $b .= rr(0, 0, 1600, 900, 0, 'url(#scrim)');
    for ($i = 0; $i < 40; $i++) {
        $b .= circ($r->range(0, 1600), $r->range(0, 900), $r->range(0.8, 2.2), '#ffffff', ['opacity' => $r->range(0.2, 0.7)]);
    }
    $b .= sparkle(1320, 170, 16, '#ffffff', 0.8) . sparkle(980, 120, 8, '#ffffff', 0.6);

    return [$defs, $b];
}

function hero_teal(Rng $r): array
{
    $c    = PAL['teal'];
    $defs = heroBase($c, $c['950'], $c['800'], $c['900'])
        . glowDef('g1', $c['400'], 0.55) . glowDef('g2', $c['300'], 0.22) . glowDef('g3', $c['600'], 0.6)
        . scrimDef($c['950'], 0.45);
    $b = rr(0, 0, 1600, 900, 0, 'url(#bg)')
        . circ(1260, 460, 620, 'url(#g3)') . circ(1260, 460, 260, 'url(#g1)') . circ(200, 120, 420, 'url(#g2)');
    $rings = '';
    for ($k = 1; $k <= 18; $k++) {
        $rings .= el('circle', ['cx' => 1260, 'cy' => 460, 'r' => (float) (60 + $k * 48), 'stroke-opacity' => (float) max(0.03, 0.24 - $k * 0.012)]);
    }
    $b .= el('g', ['fill' => 'none', 'stroke' => '#ffffff', 'stroke-width' => 1.5], $rings);
    // Orbiting dots on a few rings.
    foreach ([[3, 0.6], [6, 2.4], [9, 4.1], [12, 5.3]] as [$k, $a]) {
        $rad = 60 + $k * 48;
        $b  .= circ(1260 + $rad * cos($a), 460 + $rad * sin($a), 7, $k % 2 ? $c['300'] : $c['acc']);
    }
    $b .= circ(1260, 460, 46, $c['300'], ['opacity' => '.9']) . circ(1260, 460, 22, '#ffffff', ['opacity' => '.85']);
    $b .= el('path', ['d' => waveArea(wavePoints(-40, 1640, 800, 26, 900, 1.3, 10), 900), 'fill' => $c['950'], 'opacity' => '.55']);
    $b .= rr(0, 0, 1600, 900, 0, 'url(#scrim)');
    $b .= dotGrid(90, 640, 10, 6, 24, 2, $c['200'], 0.16);

    return [$defs, $b];
}

function hero_sunset(Rng $r): array
{
    $c    = PAL['sunset'];
    $defs = lin('bg', [[0, '#1e0b2e'], [0.45, $c['900']], [0.78, '#a3330f'], [1, $c['600']]])
        . lin('sun', [[0, '#fde68a'], [0.6, $c['400']], [1, $c['acc']]])
        . glowDef('g1', $c['500'], 0.65) . glowDef('g2', $c['acc'], 0.35)
        . lin('d1', [[0, '#7a1f2b'], [1, '#4a1230']]) . lin('d2', [[0, '#561634'], [1, '#2f0c25']]) . lin('d3', [[0, '#2f0c25'], [1, '#1a0716']])
        . el('clipPath', ['id' => 'sc'], circ(1260, 610, 180, '#000'));
    $b = rr(0, 0, 1600, 900, 0, 'url(#bg)')
        . circ(1260, 610, 600, 'url(#g1)') . circ(260, 260, 420, 'url(#g2)');
    $b .= circ(1260, 610, 180, 'url(#sun)');
    // Retro horizontal cuts through the sun.
    $cuts = '';
    for ($k = 0; $k < 6; $k++) {
        $y     = 520 + $k * 24;
        $cuts .= rr(1060, $y, 420, 3 + $k * 2.4, 0, '#4a1230');
    }
    $b .= el('g', ['clip-path' => 'url(#sc)', 'opacity' => '.85'], $cuts);
    $b .= el('path', ['d' => waveArea(wavePoints(-40, 1640, 660, 40, 1500, 0.4, 10, 14, 520), 900), 'fill' => 'url(#d1)', 'opacity' => '.95']);
    $b .= el('path', ['d' => waveArea(wavePoints(-40, 1640, 740, 46, 1200, 2.6, 10, 10, 430), 900), 'fill' => 'url(#d2)']);
    $b .= el('path', ['d' => waveArea(wavePoints(-40, 1640, 820, 28, 1000, 4.4, 10), 900), 'fill' => 'url(#d3)']);
    for ($i = 0; $i < 46; $i++) {
        $b .= circ($r->range(0, 1600), $r->range(0, 420), $r->range(0.8, 2.0), '#ffe4d1', ['opacity' => $r->range(0.25, 0.75)]);
    }

    return [$defs, $b];
}

/** Jagged mountain ridge by midpoint displacement. */
function ridge(Rng $r, float $y, float $rough, int $levels, float $bottom): string
{
    $pts = [[-20.0, $y + $r->range(-$rough, $rough)], [1620.0, $y + $r->range(-$rough, $rough)]];
    $amp = $rough;
    for ($l = 0; $l < $levels; $l++) {
        $next = [];
        for ($i = 0; $i < count($pts) - 1; $i++) {
            $next[] = $pts[$i];
            $next[] = [($pts[$i][0] + $pts[$i + 1][0]) / 2, ($pts[$i][1] + $pts[$i + 1][1]) / 2 + $r->range(-$amp, $amp)];
        }
        $next[] = $pts[count($pts) - 1];
        $pts    = $next;
        $amp   *= 0.55;
    }
    $d = 'M' . f($pts[0][0]) . ' ' . f($pts[0][1]);
    foreach (array_slice($pts, 1) as $p) {
        $d .= 'L' . f($p[0]) . ' ' . f($p[1]);
    }

    return $d . 'L1620 ' . f($bottom) . 'L-20 ' . f($bottom) . 'Z';
}

function hero_forest(Rng $r): array
{
    $c    = PAL['forest'];
    $defs = lin('bg', [[0, '#04140c'], [0.55, '#0b3a22'], [1, '#2f6b45']])
        . glowDef('g1', '#ecfccb', 0.3) . glowDef('g2', $c['500'], 0.3)
        . lin('mist', [[0, '#d1fae5', 0], [0.6, '#d1fae5', 0.13], [1, '#d1fae5', 0]]);
    $b = rr(0, 0, 1600, 900, 0, 'url(#bg)') . circ(1230, 230, 380, 'url(#g1)') . circ(300, 600, 520, 'url(#g2)');
    $b .= circ(1230, 230, 62, '#ecfccb', ['opacity' => '.92']);
    for ($i = 0; $i < 60; $i++) {
        $b .= circ($r->range(0, 1600), $r->range(0, 380), $r->range(0.7, 1.9), '#f0fdf4', ['opacity' => $r->range(0.2, 0.7)]);
    }
    $layers = [[470, 110, '#2d5f43'], [560, 90, '#1f4a33'], [640, 80, '#153a27'], [720, 60, '#0d2b1c'], [800, 40, '#071a10']];
    foreach ($layers as $i => [$y, $rough, $col]) {
        $b .= el('path', ['d' => ridge($r, $y, $rough, 7, 900), 'fill' => $col]);
        if ($i < 4) {
            $b .= rr(0, $y - 30, 1600, 150, 0, 'url(#mist)');
        }
    }

    return [$defs, $b];
}

function hero_slate(Rng $r): array
{
    $c    = PAL['slate'];
    $defs = heroBase($c, $c['950'], $c['800'], $c['900'])
        . glowDef('g1', $c['acc'], 0.45) . glowDef('g2', '#6366f1', 0.35)
        . lin('fade', [[0, '#ffffff', 0], [1, '#ffffff', 1]])
        . el('mask', ['id' => 'fm'], rr(0, 560, 1600, 340, 0, 'url(#fade)'))
        . lin('glass', [[0, '#ffffff', 0.14], [1, '#ffffff', 0.04]], 0, 0, 1, 1)
        . scrimDef($c['950'], 0.35);
    $b = rr(0, 0, 1600, 900, 0, 'url(#bg)') . circ(1180, 420, 560, 'url(#g1)') . circ(220, 160, 480, 'url(#g2)');
    // Perspective grid floor.
    $g  = '';
    $vx = 800;
    $vy = 520;
    for ($k = -16; $k <= 16; $k++) {
        $g .= 'M' . f($vx + $k * 12) . ' ' . f($vy + 40) . 'L' . f($vx + $k * 160) . ' 900';
    }
    foreach ([580, 600, 628, 664, 712, 774, 852] as $y) {
        $g .= 'M0 ' . $y . 'H1600';
    }
    $b .= el('path', ['d' => $g, 'stroke' => $c['acc'], 'stroke-opacity' => '.35', 'stroke-width' => 1.2, 'fill' => 'none', 'mask' => 'url(#fm)']);
    // Floating glass panels with UI hints.
    $panel = static function (float $x, float $y, float $w, float $h, string $acc) : string {
        return rr($x, $y, $w, $h, 18, 'url(#glass)', ['stroke' => '#ffffff', 'stroke-opacity' => '.18'])
            . rr($x + 24, $y + 24, $w * 0.45, 12, 6, '#ffffff', ['opacity' => '.45'])
            . rr($x + 24, $y + 46, $w * 0.3, 10, 5, '#ffffff', ['opacity' => '.22'])
            . rr($x + 24, $y + $h - 40, $w - 48, 14, 7, '#ffffff', ['opacity' => '.10'])
            . rr($x + 24, $y + $h - 40, ($w - 48) * 0.62, 14, 7, $acc, ['opacity' => '.85']);
    };
    $b .= $panel(1040, 200, 330, 170, $c['acc']) . $panel(1180, 420, 280, 150, '#818cf8') . $panel(960, 500, 200, 120, '#34d399');
    $b .= circ(1370, 200, 26, $c['acc'], ['opacity' => '.9']) . circ(1370, 200, 10, '#ffffff');
    $b .= rr(0, 0, 1600, 900, 0, 'url(#scrim)');
    $b .= dotGrid(100, 110, 6, 4, 24, 2, '#ffffff', 0.15);

    return [$defs, $b];
}

function hero_rose(Rng $r): array
{
    $c    = PAL['rose'];
    $defs = heroBase($c, $c['950'], $c['800'], $c['900'])
        . blurDef('bl', 70) . scrimDef($c['950'], 0.4);
    $b = rr(0, 0, 1600, 900, 0, 'url(#bg)');
    $blobs = '';
    foreach ([[1250, 260, 280, $c['500'], .55], [1000, 640, 300, $c['acc'], .4], [1450, 700, 220, $c['acc2'], .3], [300, 780, 260, $c['500'], .45], [520, 80, 200, $c['acc'], .35]] as [$x, $y, $rad, $col, $op]) {
        $blobs .= el('path', ['d' => blob($r, $x, $y, $rad, 7, 0.25), 'fill' => $col, 'opacity' => $op]);
    }
    $b .= el('g', ['filter' => 'url(#bl)'], $blobs);
    // Crisp outline accents.
    $b .= el('path', ['d' => blob($r, 1200, 450, 300, 8, 0.12), 'fill' => 'none', 'stroke' => '#ffffff', 'stroke-opacity' => '.18', 'stroke-width' => 2]);
    $b .= el('path', ['d' => blob($r, 1200, 450, 240, 8, 0.12), 'fill' => 'none', 'stroke' => '#ffffff', 'stroke-opacity' => '.10', 'stroke-width' => 2]);
    $b .= circ(1420, 210, 40, '#ffffff', ['opacity' => '.12']) . circ(980, 760, 18, '#ffffff', ['opacity' => '.2']);
    $b .= rr(0, 0, 1600, 900, 0, 'url(#scrim)');
    $b .= sparkle(1100, 180, 14, '#ffffff', 0.7) . sparkle(1480, 520, 10, '#ffffff', 0.5);

    return [$defs, $b];
}

function hero_gold(Rng $r): array
{
    $c    = PAL['gold'];
    $defs = lin('bg', [[0, '#120a03'], [0.5, '#2e1a06'], [1, '#5a300b']], 0, 0, 1, 1)
        . glowDef('g1', $c['500'], 0.5) . glowDef('g2', $c['300'], 0.3)
        . lin('beam', [[0, $c['200'], 0.22], [1, $c['200'], 0]], 1, 0, 0, 1)
        . blurDef('bl', 6) . blurDef('bl2', 26);
    $b = rr(0, 0, 1600, 900, 0, 'url(#bg)') . circ(1300, 300, 700, 'url(#g1)') . circ(1500, 80, 300, 'url(#g2)');
    $b .= el('path', ['d' => 'M1600 0L1600 260L520 900L180 900Z', 'fill' => 'url(#beam)', 'filter' => 'url(#bl2)']);
    $soft = '';
    $sharp = '';
    for ($i = 0; $i < 34; $i++) {
        $x   = $r->range(700, 1600);
        $y   = $r->range(0, 900);
        $rad = $r->range(8, 70);
        $col = [$c['400'], $c['300'], $c['200'], '#fff7d6'][$i % 4];
        $op  = $r->range(0.08, 0.32);
        if ($i % 3 === 0) {
            $sharp .= circ($x, $y, $rad, $col, ['opacity' => $op, 'stroke' => $c['200'], 'stroke-opacity' => '.25', 'stroke-width' => 1.5]);
        } else {
            $soft .= circ($x, $y, $rad, $col, ['opacity' => $op]);
        }
    }
    $b .= el('g', ['filter' => 'url(#bl)'], $soft) . $sharp;
    // Fine gold arcs.
    $b .= el('path', ['d' => 'M760 900C900 560 1180 380 1600 330', 'stroke' => $c['300'], 'stroke-opacity' => '.45', 'stroke-width' => 1.6, 'fill' => 'none']);
    $b .= el('path', ['d' => 'M840 900C980 600 1240 440 1600 400', 'stroke' => $c['300'], 'stroke-opacity' => '.25', 'stroke-width' => 1.2, 'fill' => 'none']);
    $b .= sparkle(1240, 180, 18, '#fff7d6', 0.85) . sparkle(1460, 460, 10, '#fff7d6', 0.6);

    return [$defs, $b];
}

