function vignetteMask(string $id, bool $centerVisible): string
{
    $a = $centerVisible ? 1 : 0;

    return rad($id . 'g', [[0, '#ffffff', $a], [1, '#ffffff', 1 - $a]], ['cx' => '.5', 'cy' => '.5', 'r' => '.75'])
        . el('mask', ['id' => $id], rr(0, 0, 1600, 900, 0, 'url(#' . $id . 'g)'));
}

