function bg_forest(Rng $r): array
{
    $c    = PAL['forest'];
    $defs = lin('bg', [[0, $c['950']], [1, $c['900']]], 0, 0, 1, 1) . glowDef('g1', $c['600'], 0.3);
    $b    = rr(0, 0, 1600, 900, 0, 'url(#bg)') . circ(1300, 650, 600, 'url(#g1)');
    $topo = '';
    foreach ([[1250, 620, 15], [260, 180, 11], [820, 900, 8]] as $ci => [$cx, $cy, $n]) {
        $rr2  = new Rng(9100 + $ci);
        $base = [];
        for ($i = 0; $i < 9; $i++) {
            $base[] = 1 + $rr2->range(-0.18, 0.18);
        }
        for ($k = 1; $k <= $n; $k++) {
            $pts = [];
            for ($i = 0; $i < 9; $i++) {
                $a     = 2 * M_PI * $i / 9 + $k * 0.05;
                $rad   = $k * 42 * $base[$i] * (1 + 0.04 * sin($k + $i));
                $pts[] = [$cx + $rad * cos($a), $cy + $rad * sin($a) * 0.72];
            }
            $topo .= el('path', ['d' => smooth($pts, true)]);
        }
    }
    $b .= el('g', ['fill' => 'none', 'stroke' => $c['300'], 'stroke-width' => 1.3, 'opacity' => '.14'], $topo);

    return [$defs, $b];
}

function bg_gold(Rng $r): array
