        $tile . el('g', ['transform' => 'translate(80 0)'], $tile2) . el('g', ['transform' => 'translate(0 80)'], $tile2) . el('g', ['transform' => 'translate(80 80)'], $tile))
        . lin('fade', [[0, '#fffbeb', 0.45], [1, '#fffbeb', 0.85]], 0, 0, 1, 0);
    $b = rr(0, 0, 1600, 900, 0, 'url(#p)') . rr(0, 0, 1600, 900, 0, 'url(#fade)');

