function cardBackdrop(Rng $r, array $c, string $bgA, string $bgB): array
{
    $defs = lin('bg', [[0, $bgA], [1, $bgB]], 0, 0, 1, 1) . shadowDef('sh', $c['900'], 0.16) . glowDef('gl', '#ffffff', 0.75);
    $b    = rr(0, 0, 1200, 900, 0, 'url(#bg)')
        . circ(600, 430, 420, 'url(#gl)')
        . el('path', ['d' => blob($r, 600, 450, 330, 8, 0.12), 'fill' => $c['200'], 'opacity' => '.55'])
        . dotGrid(90, 90, 6, 4, 22, 3, $c['300'], 0.7)
        . dotGrid(990, 700, 5, 5, 22, 3, $c['300'], 0.7);

    return [$defs, $b];
}

function card_blue(Rng $r): array
{
    $c = PAL['blue'];
    [$defs, $b] = cardBackdrop($r, $c, '#f3f8ff', $c['100']);
    $defs .= lin('bar', [[0, $c['400']], [1, $c['700']]]) . lin('bar2', [[0, $c['acc']], [1, $c['500']]]);
    $b .= el('ellipse', ['cx' => 600, 'cy' => 720, 'rx' => 330, 'ry' => 22, 'fill' => $c['900'], 'opacity' => '.08']);
    $b .= rr(270, 220, 620, 470, 30, '#ffffff', ['filter' => 'url(#sh)']);
    $b .= circ(312, 262, 8, '#f87171') . circ(338, 262, 8, '#fbbf24') . circ(364, 262, 8, '#34d399');
    $b .= rr(310, 300, 190, 18, 9, $c['900'], ['opacity' => '.85']) . rr(310, 330, 120, 12, 6, $c['300']);
    // Grid lines.
    $grid = '';
    foreach ([420, 480, 540, 600] as $y) {
        $grid .= 'M310 ' . $y . 'H850';
    }
    $b .= el('path', ['d' => $grid, 'stroke' => $c['100'], 'stroke-width' => 2]);
    $heights = [110, 170, 130, 210, 175, 250];
    $pts     = [];
    foreach ($heights as $i => $h) {
        $x   = 350 + $i * 86;
        $b  .= rr($x, 640 - $h, 50, $h, 10, $i === 5 ? 'url(#bar2)' : 'url(#bar)');
        $pts[] = [$x + 25.0, 640 - $h - 46.0 - ($i % 2) * 10];
    }
    $b .= el('path', ['d' => smooth($pts), 'fill' => 'none', 'stroke' => $c['acc2'], 'stroke-width' => 6, 'stroke-linecap' => 'round']);
    foreach ($pts as $p) {
        $b .= circ($p[0], $p[1], 9, '#ffffff', ['stroke' => $c['acc2'], 'stroke-width' => 5]);
    }
    // Donut card.
    $b .= rr(790, 140, 280, 210, 26, '#ffffff', ['filter' => 'url(#sh)']);
    $b .= circ(880, 245, 58, 'none', ['stroke' => $c['100'], 'stroke-width' => 24]);
    $b .= circ(880, 245, 58, 'none', ['stroke' => $c['600'], 'stroke-width' => 24, 'stroke-dasharray' => '255 400', 'transform' => 'rotate(-90 880 245)', 'stroke-linecap' => 'round']);
    $b .= rr(960, 205, 80, 14, 7, $c['900'], ['opacity' => '.8']) . rr(960, 232, 60, 10, 5, $c['300']) . rr(960, 258, 70, 10, 5, $c['200']);
    // KPI pill.
    $b .= rr(110, 590, 230, 120, 24, '#ffffff', ['filter' => 'url(#sh)']);
    $b .= circ(166, 650, 32, '#dcfce7') . el('path', ['d' => 'M152 662L166 642L180 662M166 642V670', 'stroke' => '#16a34a', 'stroke-width' => 6, 'fill' => 'none', 'stroke-linecap' => 'round', 'stroke-linejoin' => 'round']);
    $b .= rr(214, 628, 100, 18, 9, $c['900'], ['opacity' => '.85']) . rr(214, 658, 70, 12, 6, '#86efac');
    $b .= sparkle(1060, 470, 18, $c['acc2']) . plus(160, 400, 14, $c['400'], 6);

    return [$defs, $b];
}

