    $b .= el('circle', ['cx' => 600, 'cy' => 440, 'r' => 230, 'fill' => 'none', 'stroke' => $c['300'], 'stroke-width' => 2, 'opacity' => '.7']);
    $b .= el('ellipse', ['cx' => 600, 'cy' => 740, 'rx' => 170, 'ry' => 20, 'fill' => $c['900'], 'opacity' => '.1']);
    $shield = 'M600 170L800 244C800 244 806 420 768 516C726 620 600 690 600 690C600 690 474 620 432 516C394 420 400 244 400 244Z';
    $b .= el('path', ['d' => $shield, 'fill' => 'url(#sh1)', 'filter' => 'url(#sh)']);
    $b .= el('path', ['d' => 'M600 170L400 244C400 244 394 420 432 516C474 620 600 690 600 690Z', 'fill' => 'url(#sh2)']);
    $b .= el('path', ['d' => 'M600 222L756 280C756 280 760 420 730 496C698 578 600 634 600 634C600 634 502 578 470 496C440 420 444 280 444 280Z', 'fill' => 'none', 'stroke' => '#ffffff', 'stroke-opacity' => '.35', 'stroke-width' => 4]);
    $b .= el('path', ['d' => 'M520 440L582 500L694 384', 'fill' => 'none', 'stroke' => '#ffffff', 'stroke-width' => 38, 'stroke-linecap' => 'round', 'stroke-linejoin' => 'round']);
    // Orbiting badges.
    foreach ([[360, 290, 'lock'], [858, 560, 'check'], [880, 250, 'dot']] as [$x, $y, $kind]) {
        $b .= circ($x, $y, 44, '#ffffff', ['filter' => 'url(#sh)']);
        if ($kind === 'lock') {
            $b .= rr($x - 18, $y - 4, 36, 28, 6, $c['600']) . el('path', ['d' => 'M' . ($x - 11) . ' ' . ($y - 4) . 'V' . ($y - 12) . 'A11 11 0 0 1 ' . ($x + 11) . ' ' . ($y - 12) . 'V' . ($y - 4), 'fill' => 'none', 'stroke' => $c['600'], 'stroke-width' => 6]);
        } elseif ($kind === 'check') {
            $b .= circ($x, $y, 24, $c['acc']) . el('path', ['d' => 'M' . ($x - 10) . ' ' . $y . 'L' . ($x - 2) . ' ' . ($y + 8) . 'L' . ($x + 12) . ' ' . ($y - 8), 'fill' => 'none', 'stroke' => '#ffffff', 'stroke-width' => 6, 'stroke-linecap' => 'round', 'stroke-linejoin' => 'round']);
        } else {
            $b .= circ($x, $y, 14, $c['acc2']);
        }
    }
    $b .= sparkle(300, 600, 16, $c['500']) . plus(980, 420, 12, $c['400'], 6);

    return [$defs, $b];
}

function card_sunset(Rng $r): array
{
    $c = PAL['sunset'];
    [$defs, $b] = cardBackdrop($r, $c, '#fffaf5', $c['100']);
    $defs .= lin('body', [[0, '#ffffff'], [1, '#ffe8d6']], 0, 0, 1, 0) . lin('fl', [[0, '#fde047'], [1, $c['500']]]) . lin('fin', [[0, $c['acc']], [1, '#be123c']]);
    // Trail.
    $b .= el('path', ['d' => 'M200 820C330 760 380 660 470 600', 'fill' => 'none', 'stroke' => $c['300'], 'stroke-width' => 6, 'stroke-dasharray' => '2 18', 'stroke-linecap' => 'round']);
    // Clouds.
    $cloud = static fn (float $x, float $y, float $s, float $op): string => el('g', ['fill' => '#ffffff', 'opacity' => $op],
        circ($x, $y, 46 * $s, '#ffffff') . circ($x + 52 * $s, $y - 22 * $s, 60 * $s, '#ffffff') . circ($x + 116 * $s, $y, 48 * $s, '#ffffff') . rr($x - 20 * $s, $y, 170 * $s, 46 * $s, 23 * $s, '#ffffff'));
    $b .= $cloud(200, 720, 1.1, 1) . $cloud(860, 640, 0.8, 0.9) . $cloud(160, 300, 0.6, 0.85);
    // Rocket, drawn upright then tilted.
    $rk  = el('path', ['d' => 'M-40 150C-40 210 0 280 0 300C0 280 40 210 40 150Z', 'fill' => 'url(#fl)']);
    $rk .= el('path', ['d' => 'M-20 150C-20 190 0 230 0 244C0 230 20 190 20 150Z', 'fill' => '#fff7ed']);
    $rk .= el('path', ['d' => 'M-80 40L-150 150L-150 180L-78 140Z', 'fill' => 'url(#fin)']);
    $rk .= el('path', ['d' => 'M80 40L150 150L150 180L78 140Z', 'fill' => 'url(#fin)']);
    $rk .= rr(-52, 124, 104, 34, 10, '#64748b');
    $rk .= el('path', ['d' => 'M0 -250C80 -190 96 -70 84 130H-84C-96 -70 -80 -190 0 -250Z', 'fill' => 'url(#body)', 'filter' => 'url(#sh)']);
    $rk .= el('path', ['d' => 'M0 -250C46 -215 70 -170 80 -122H-80C-70 -170 -46 -215 0 -250Z', 'fill' => 'url(#fin)']);
    $rk .= circ(0, -30, 44, $c['700']) . circ(0, -30, 32, '#1e293b') . el('path', ['d' => 'M-16 -46A22 22 0 0 1 10 -54', 'stroke' => '#ffffff', 'stroke-width' => 6, 'fill' => 'none', 'stroke-linecap' => 'round', 'opacity' => '.8']);
    $rk .= el('path', ['d' => 'M-6 140V40', 'stroke' => $c['200'], 'stroke-width' => 8, 'stroke-linecap' => 'round']);
    $b  .= el('g', ['transform' => 'translate(640 420) rotate(38)'], $rk);
    $b  .= sparkle(940, 220, 22, $c['500']) . sparkle(1030, 330, 12, $c['acc']) . sparkle(300, 160, 14, $c['400']) . plus(820, 140, 12, $c['400'], 6);
    $b  .= circ(1000, 470, 8, $c['300']) . circ(240, 480, 10, $c['acc'], ['opacity' => '.6']);

    return [$defs, $b];
}

function card_forest(Rng $r): array
{
    $c = PAL['forest'];
    [$defs, $b] = cardBackdrop($r, $c, '#f4fdf6', $c['100']);
    $defs .= lin('lf', [[0, $c['400']], [1, $c['700']]], 0, 0, 1, 1) . lin('lf2', [[0, $c['300']], [1, $c['600']]], 1, 0, 0, 1)
        . lin('pot', [[0, '#e7a17a'], [1, '#c2410c']]) . glowDef('sun', '#fde047', 0.75);
    $b .= circ(860, 230, 170, 'url(#sun)') . circ(860, 230, 64, '#fde68a');
    $b .= el('ellipse', ['cx' => 600, 'cy' => 780, 'rx' => 220, 'ry' => 22, 'fill' => $c['900'], 'opacity' => '.1']);
    $leaf = static function (float $x, float $y, float $len, float $wid, float $ang, string $fill): string {
        $d = 'M0 0C' . f($wid) . ' ' . f(-$len * 0.25) . ' ' . f($wid * 0.9) . ' ' . f(-$len * 0.8) . ' 0 ' . f(-$len)
            . 'C' . f(-$wid * 0.9) . ' ' . f(-$len * 0.8) . ' ' . f(-$wid) . ' ' . f(-$len * 0.25) . ' 0 0Z';
        $v = 'M0 -6V' . f(-$len * 0.92);
        for ($k = 1; $k <= 4; $k++) {
            $yy = -$len * (0.18 * $k);
            $v .= 'M0 ' . f($yy) . 'Q' . f($wid * 0.35) . ' ' . f($yy - 14) . ' ' . f($wid * 0.62) . ' ' . f($yy - 40)
                . 'M0 ' . f($yy) . 'Q' . f(-$wid * 0.35) . ' ' . f($yy - 14) . ' ' . f(-$wid * 0.62) . ' ' . f($yy - 40);
        }

        return el('g', ['transform' => 'translate(' . f($x) . ' ' . f($y) . ') rotate(' . f($ang) . ')'],
            el('path', ['d' => $d, 'fill' => $fill]) . el('path', ['d' => $v, 'fill' => 'none', 'stroke' => '#ffffff', 'stroke-opacity' => '.45', 'stroke-width' => 4, 'stroke-linecap' => 'round']));
    };
    $b .= el('path', ['d' => 'M600 640C596 560 560 480 520 420M600 640C606 560 640 470 700 400M600 640V330', 'stroke' => $c['700'], 'stroke-width' => 10, 'fill' => 'none', 'stroke-linecap' => 'round']);
    $b .= $leaf(520, 430, 240, 95, -48, 'url(#lf2)') . $leaf(700, 410, 260, 100, 44, 'url(#lf)') . $leaf(600, 340, 230, 92, 0, 'url(#lf)');
    $b .= el('path', ['d' => 'M470 630H730L700 780Q696 790 684 790H516Q504 790 500 780Z', 'fill' => 'url(#pot)', 'filter' => 'url(#sh)']);
    $b .= rr(452, 610, 296, 46, 16, '#ea8a5c');
    $b .= circ(330, 290, 10, $c['400']) . circ(370, 250, 6, $c['300']) . sparkle(1000, 520, 18, '#facc15') . plus(220, 520, 12, $c['400'], 6);

    return [$defs, $b];
}

function card_gold(Rng $r): array
{
    $c = PAL['gold'];
    [$defs, $b] = cardBackdrop($r, $c, '#fffdf5', $c['100']);
    $defs .= rad('bulb', [[0, '#fffbe6'], [0.6, $c['200']], [1, $c['400']]], ['cx' => '.4', 'cy' => '.35', 'r' => '.75']) . glowDef('glow', '#fde047', 0.8) . lin('base', [[0, '#94a3b8'], [1, '#475569']], 0, 0, 1, 0);
    $b .= circ(600, 360, 330, 'url(#glow)');
    $rays = '';
    for ($i = 0; $i < 10; $i++) {
        $a = -M_PI + $i * M_PI / 9;
        if ($i === 0 || $i === 9) {
            $a += $i === 0 ? 0.25 : -0.25;
        }
        $rays .= 'M' . f(600 + 245 * cos($a)) . ' ' . f(360 + 245 * sin($a)) . 'L' . f(600 + 300 * cos($a)) . ' ' . f(360 + 300 * sin($a));
    }
    $b .= el('path', ['d' => $rays, 'stroke' => $c['500'], 'stroke-width' => 14, 'stroke-linecap' => 'round']);
    $b .= el('ellipse', ['cx' => 600, 'cy' => 770, 'rx' => 140, 'ry' => 18, 'fill' => $c['900'], 'opacity' => '.12']);
    $b .= el('path', ['d' => 'M600 170C708 170 790 252 790 358C790 430 750 476 720 512C702 534 696 556 696 580H504C504 556 498 534 480 512C450 476 410 430 410 358C410 252 492 170 600 170Z', 'fill' => 'url(#bulb)', 'filter' => 'url(#sh)', 'stroke' => $c['400'], 'stroke-width' => 4]);
    $b .= el('path', ['d' => 'M480 330C486 270 524 232 570 218', 'stroke' => '#ffffff', 'stroke-width' => 16, 'stroke-linecap' => 'round', 'fill' => 'none', 'opacity' => '.85']);
    $b .= el('path', ['d' => 'M556 580V470L530 420Q600 380 670 420L644 470V580', 'stroke' => $c['700'], 'stroke-width' => 8, 'fill' => 'none', 'stroke-linejoin' => 'round']);
    $b .= rr(510, 580, 180, 34, 14, 'url(#base)') . rr(516, 620, 168, 30, 14, 'url(#base)') . rr(524, 656, 152, 30, 14, 'url(#base)');
    $b .= el('path', ['d' => 'M556 690H644Q644 730 600 734Q556 730 556 690Z', 'fill' => '#334155']);
    $b .= sparkle(900, 600, 20, $c['500']) . sparkle(290, 620, 14, $c['400']) . plus(940, 190, 12, $c['400'], 6);

    return [$defs, $b];
}

function card_rose(Rng $r): array
{
    $c = PAL['rose'];
    [$defs, $b] = cardBackdrop($r, $c, '#fff8f9', $c['100']);
    $defs .= lin('ra', [[0, $c['400']], [1, $c['700']]], 0, 0, 1, 1) . lin('rb', [[0, '#e879f9'], [1, '#9333ea']], 1, 0, 0, 1)
        . el('clipPath', ['id' => 'ov'], circ(600, 323, 82, '#000'));
    $ringA = el('circle', ['cx' => 515, 'cy' => 450, 'r' => 150, 'fill' => 'none', 'stroke' => 'url(#ra)', 'stroke-width' => 58]);
    $ringB = el('circle', ['cx' => 685, 'cy' => 450, 'r' => 150, 'fill' => 'none', 'stroke' => 'url(#rb)', 'stroke-width' => 58]);
    $b .= el('ellipse', ['cx' => 600, 'cy' => 700, 'rx' => 280, 'ry' => 20, 'fill' => $c['900'], 'opacity' => '.1']);
    $b .= el('g', ['filter' => 'url(#sh)'], $ringA . $ringB);
    $b .= el('g', ['clip-path' => 'url(#ov)'], $ringA);
    // Highlights.
    $b .= el('path', ['d' => 'M410 360A130 130 0 0 1 480 312', 'stroke' => '#ffffff', 'stroke-opacity' => '.55', 'stroke-width' => 12, 'fill' => 'none', 'stroke-linecap' => 'round']);
    $b .= el('path', ['d' => 'M790 540A130 130 0 0 1 740 590', 'stroke' => '#ffffff', 'stroke-opacity' => '.4', 'stroke-width' => 12, 'fill' => 'none', 'stroke-linecap' => 'round']);
    // Connection nodes.
    $b .= el('path', ['d' => 'M220 250Q300 220 360 300M980 650Q900 690 840 610', 'stroke' => $c['300'], 'stroke-width' => 5, 'fill' => 'none', 'stroke-dasharray' => '2 14', 'stroke-linecap' => 'round']);
    $b .= circ(210, 250, 34, '#ffffff', ['filter' => 'url(#sh)']) . circ(210, 250, 16, $c['500']);
    $b .= circ(990, 650, 34, '#ffffff', ['filter' => 'url(#sh)']) . circ(990, 650, 16, '#a855f7');
    $heart = 'M600 230C600 230 572 200 552 214C532 228 540 254 600 290C660 254 668 228 648 214C628 200 600 230 600 230Z';
    $b .= el('path', ['d' => $heart, 'fill' => $c['500'], 'transform' => 'translate(0 -40)']);
    $b .= sparkle(960, 230, 18, $c['acc2']) . plus(260, 640, 12, $c['400'], 6) . sparkle(870, 790, 10, $c['400']);

    return [$defs, $b];
}

function card_slate(Rng $r): array
{
    $c = PAL['slate'];
    [$defs, $b] = cardBackdrop($r, $c, $c['50'], $c['200']);
    $defs .= lin('pin', [[0, '#fb7185'], [1, '#be123c']], 0, 0, 1, 1)
        . el('clipPath', ['id' => 'map'], el('path', ['d' => 'M220 330L440 260L660 330L900 260V640L660 710L440 640L220 710Z']));
    $b .= el('path', ['d' => 'M220 330L440 260L660 330L900 260V640L660 710L440 640L220 710Z', 'fill' => '#ffffff', 'filter' => 'url(#sh)']);
    $m  = el('path', ['d' => 'M440 260L660 330V710L440 640Z', 'fill' => $c['100']]);
    $m .= el('path', ['d' => blob($r, 330, 450, 80, 6, 0.2), 'fill' => '#bbf7d0']) . el('path', ['d' => blob($r, 780, 600, 70, 6, 0.2), 'fill' => '#bbf7d0']);
    $m .= el('path', ['d' => 'M200 600C320 560 380 640 500 580C620 520 640 420 760 420C820 420 880 380 920 360', 'stroke' => '#93c5fd', 'stroke-width' => 26, 'fill' => 'none']);
    $m .= el('path', ['d' => 'M200 420H940M340 250V720M560 250V720M200 520L940 340', 'stroke' => $c['300'], 'stroke-width' => 10, 'fill' => 'none']);
    $m .= el('path', ['d' => 'M660 330V710M440 260V640', 'stroke' => $c['900'], 'stroke-opacity' => '.06', 'stroke-width' => 6]);
    $b .= el('g', ['clip-path' => 'url(#map)'], $m);
    $b .= el('path', ['d' => 'M300 640C380 600 400 520 480 520S600 560 620 470', 'stroke' => $c['acc'], 'stroke-width' => 8, 'fill' => 'none', 'stroke-dasharray' => '4 16', 'stroke-linecap' => 'round']);
    $b .= circ(300, 640, 14, '#ffffff', ['stroke' => $c['acc'], 'stroke-width' => 7]);
    $b .= el('ellipse', ['cx' => 620, 'cy' => 470, 'rx' => 60, 'ry' => 16, 'fill' => $c['900'], 'opacity' => '.2']);
    $b .= el('path', ['d' => 'M620 470C620 470 500 340 500 250A120 120 0 1 1 740 250C740 340 620 470 620 470Z', 'fill' => 'url(#pin)', 'filter' => 'url(#sh)']);
    $b .= circ(620, 250, 46, '#ffffff') . circ(620, 250, 20, $c['acc2'], ['opacity' => '.35']);
    $b .= sparkle(900, 170, 18, $c['acc']) . plus(240, 200, 12, $c['400'], 6);

    return [$defs, $b];
}

// ---------------------------------------------------------------------------
// SQUARES (800×800) — gallery / feature graphics.
// ---------------------------------------------------------------------------

function sq_slate(Rng $r): array
{
    $c    = PAL['slate'];
    $defs = lin('bg', [[0, $c['100']], [1, $c['300']]], 0, 0, 1, 1) . lin('a', [[0, $c['500']], [1, $c['700']]], 0, 0, 1, 1) . lin('b', [[0, '#ffffff'], [1, $c['200']]], 0, 0, 1, 1)
        . shadowDef('sh', $c['900'], 0.18, 14, 18);
    $b = rr(0, 0, 800, 800, 0, 'url(#bg)');
    $b .= el('g', ['filter' => 'url(#sh)'],
        circ(320, 330, 190, 'url(#a)')
        . rr(380, 360, 260, 260, 28, 'url(#b)')
        . el('path', ['d' => 'M150 650A150 150 0 0 1 450 650Z', 'fill' => $c['400']]));
    $b .= circ(510, 490, 62, $c['acc']);
    $b .= el('path', ['d' => 'M560 150A110 110 0 0 1 670 260', 'stroke' => $c['600'], 'stroke-width' => 22, 'fill' => 'none', 'stroke-linecap' => 'round']);
    $b .= dotGrid(110, 110, 4, 4, 22, 4, $c['500'], 0.5);
    $b .= el('path', ['d' => 'M580 680L630 630L680 680L730 630', 'stroke' => $c['600'], 'stroke-width' => 10, 'fill' => 'none', 'stroke-linecap' => 'round', 'stroke-linejoin' => 'round']);

    return [$defs, $b];
}

function sq_blue(Rng $r): array
{
    $c    = PAL['blue'];
    $defs = lin('sky', [[0, $c['950']], [0.6, $c['800']], [1, $c['600']]]) . glowDef('moon', '#e0f2fe', 0.55);
    $b    = rr(0, 0, 800, 800, 0, 'url(#sky)');
    for ($i = 0; $i < 40; $i++) {
        $b .= circ($r->range(0, 800), $r->range(0, 420), $r->range(0.8, 2.2), '#ffffff', ['opacity' => $r->range(0.3, 0.9)]);
    }
    $b .= circ(560, 250, 200, 'url(#moon)') . circ(560, 250, 74, '#f0f9ff') . circ(536, 232, 14, '#dbeafe') . circ(588, 276, 10, '#dbeafe');
    $layers = [[500, 26, $c['700'], 0.9], [560, 24, $c['800'], 0.95], [630, 20, '#152c6e', 1], [710, 16, $c['900'], 1]];
    foreach ($layers as $i => [$y, $amp, $col, $op]) {
        $b .= el('path', ['d' => waveArea(wavePoints(-20, 820, $y, $amp, 320 + $i * 40, $i * 1.3, 10), 800), 'fill' => $col, 'opacity' => $op]);
    }
    $b .= el('path', ['d' => 'M520 520H600M500 560H620M530 600H590M545 650H575', 'stroke' => '#e0f2fe', 'stroke-opacity' => '.5', 'stroke-width' => 5, 'stroke-linecap' => 'round']);

    return [$defs, $b];
}

function sq_purple(Rng $r): array
{
    $c    = PAL['purple'];
    $defs = lin('bg', [[0, $c['950']], [1, $c['800']]], 0, 0, 1, 1) . glowDef('neb', $c['acc'], 0.35) . glowDef('neb2', $c['500'], 0.5)
        . lin('pl', [[0, '#fbcfe8'], [0.5, $c['400']], [1, $c['700']]], 0, 0, 1, 1)
        . lin('ring', [[0, '#ffffff', 0.1], [0.5, '#fde68a', 0.9], [1, '#ffffff', 0.1]], 0, 0, 1, 0);
    $b = rr(0, 0, 800, 800, 0, 'url(#bg)') . circ(160, 160, 360, 'url(#neb)') . circ(620, 640, 380, 'url(#neb2)');
    for ($i = 0; $i < 70; $i++) {
        $b .= circ($r->range(0, 800), $r->range(0, 800), $r->range(0.8, 2.4), '#ffffff', ['opacity' => $r->range(0.3, 0.9)]);
    }
    $ring = el('ellipse', ['cx' => 400, 'cy' => 400, 'rx' => 300, 'ry' => 62, 'fill' => 'none', 'stroke' => 'url(#ring)', 'stroke-width' => 18, 'transform' => 'rotate(-18 400 400)']);
    $b .= $ring;
    $b .= circ(400, 400, 170, 'url(#pl)');
    $b .= el('path', ['d' => 'M262 330C330 350 470 340 540 300M240 420C340 450 480 440 565 400', 'stroke' => '#ffffff', 'stroke-opacity' => '.18', 'stroke-width' => 18, 'fill' => 'none', 'stroke-linecap' => 'round']);
    // Front half of the ring (lower arc) over the planet.
    $b .= el('g', ['transform' => 'rotate(-18 400 400)'], el('path', ['d' => 'M100 400A300 62 0 0 0 700 400', 'fill' => 'none', 'stroke' => 'url(#ring)', 'stroke-width' => 18]));
    $b .= circ(650, 170, 26, '#fde68a') . circ(150, 640, 14, $c['300']);
    $b .= sparkle(660, 560, 16, '#ffffff', 0.9) . sparkle(130, 300, 10, '#ffffff', 0.7);

    return [$defs, $b];
}

function sq_teal(Rng $r): array
{
    $c    = PAL['teal'];
    $cols = [$c['900'], $c['600'], $c['300'], $c['100'], $c['acc'], $c['acc2'], $c['400']];
    $b    = rr(0, 0, 800, 800, 0, $c['50']);
    for ($j = 0; $j < 4; $j++) {
        for ($i = 0; $i < 4; $i++) {
            $x    = $i * 200;
            $y    = $j * 200;
            $bgc  = $cols[$r->int(0, 3)];
            $fgc  = $cols[$r->int(0, 6)];
            if ($fgc === $bgc) {
                $fgc = $c['50'];
            }
            $b   .= rr($x, $y, 200, 200, 0, $bgc);
            $kind = $r->int(0, 4);
            $rot  = 90 * $r->int(0, 3);
            $g    = match ($kind) {
                0 => el('path', ['d' => 'M0 200A200 200 0 0 1 200 0V200Z', 'fill' => $fgc]),
                1 => el('path', ['d' => 'M0 100A100 100 0 0 1 200 100Z', 'fill' => $fgc]),
                2 => circ(100, 100, 70, $fgc),
                3 => el('path', ['d' => 'M0 0H200L0 200Z', 'fill' => $fgc]),
                default => circ(100, 100, 70, 'none', ['stroke' => $fgc, 'stroke-width' => 26]),
            };
            $b .= el('g', ['transform' => 'translate(' . $x . ' ' . $y . ') rotate(' . $rot . ' 100 100)'], $g);
        }
    }

    return ['', $b];
}

function sq_sunset(Rng $r): array
{
    $c    = PAL['sunset'];
    $defs = lin('sky', [[0, '#fde68a'], [0.45, $c['300']], [1, '#f472b6']]) . lin('sun', [[0, '#fff7d6'], [1, '#fde047']]) . glowDef('g', '#fff7d6', 0.7);
    $b    = rr(0, 0, 800, 800, 0, 'url(#sky)') . circ(400, 420, 260, 'url(#g)') . circ(400, 420, 120, 'url(#sun)');
    // Mountain ranges: a few broad peaks per layer, alternating sides.
    $layers = [[470, 150, '#f6a07a', 0], [530, 130, '#e8746a', 1], [600, 110, '#c2456a', 0], [670, 80, '#8f2f5e', 1], [740, 50, '#5b1f4f', 0]];
    foreach ($layers as [$y, $hgt, $col, $flip]) {
        $pts = [];
        for ($k = 0; $k <= 4; $k++) {
            $peak  = ($k + $flip) % 2 === 1;
            $pts[] = [-60 + $k * 230.0 + $r->range(-30, 30), $peak ? $y - $hgt * $r->range(0.7, 1.0) : $y + $r->range(0, 20)];
        }
        $b .= el('path', ['d' => waveArea($pts, 800), 'fill' => $col]);
    }
    $b .= el('path', ['d' => 'M200 210q14-14 28 0q14-14 28 0M290 170q10-10 20 0q10-10 20 0', 'stroke' => '#7c2d12', 'stroke-width' => 4, 'fill' => 'none', 'stroke-linecap' => 'round', 'opacity' => '.6']);

    return [$defs, $b];
}

function sq_forest(Rng $r): array
{
    $c    = PAL['forest'];
    $defs = lin('bg', [[0, '#f0fdf4'], [1, '#d9f5e3']]) . lin('lf', [[0, $c['400']], [1, $c['700']]], 0, 0, 1, 1) . lin('lf2', [[0, $c['500']], [1, $c['800']]], 1, 0, 0, 1)
        . lin('pot', [[0, '#f5f0e8'], [1, '#d6cbbb']], 0, 0, 1, 0);
    $b = rr(0, 0, 800, 800, 0, 'url(#bg)') . circ(560, 260, 150, '#fef9c3') . rr(0, 640, 800, 160, 0, '#c8ecd4');
    $leafPath = static function (float $len, float $wid): string {
        return 'M0 0C' . f($wid) . ' ' . f(-$len * 0.3) . ' ' . f($wid * 0.8) . ' ' . f(-$len * 0.85) . ' 0 ' . f(-$len)
            . 'C' . f(-$wid * 0.8) . ' ' . f(-$len * 0.85) . ' ' . f(-$wid) . ' ' . f(-$len * 0.3) . ' 0 0Z';
    };
    $leaves = [[-62, 230, 80, 'url(#lf2)'], [-30, 270, 86, 'url(#lf)'], [0, 300, 90, 'url(#lf2)'], [28, 270, 86, 'url(#lf)'], [60, 230, 80, 'url(#lf2)'], [-88, 180, 66, 'url(#lf)'], [86, 180, 66, 'url(#lf)']];
    foreach ($leaves as [$ang, $len, $wid, $fill]) {
        $b .= el('g', ['transform' => 'translate(400 520) rotate(' . $ang . ')'],
            el('path', ['d' => $leafPath($len, $wid), 'fill' => $fill])
            . el('path', ['d' => 'M0 -10V' . f(-$len * 0.9), 'stroke' => '#ffffff', 'stroke-opacity' => '.35', 'stroke-width' => 4, 'stroke-linecap' => 'round']));
    }
    $b .= el('path', ['d' => 'M290 520H510L486 690Q482 700 470 700H330Q318 700 314 690Z', 'fill' => 'url(#pot)']);
    $b .= rr(276, 500, 248, 40, 14, '#ece5da') . el('path', ['d' => 'M300 600H500', 'stroke' => $c['600'], 'stroke-width' => 6, 'opacity' => '.5']);

    return [$defs, $b];
}

function sq_rose(Rng $r): array
{
    $c    = PAL['rose'];
    $defs = lin('bg', [[0, $c['50']], [1, $c['100']]], 0, 0, 1, 1) . lin('p1', [[0, $c['300']], [1, $c['500']]]) . lin('p2', [[0, $c['400']], [1, $c['700']]]) . rad('cn', [[0, '#fde68a'], [1, '#f59e0b']]);
    $b    = rr(0, 0, 800, 800, 0, 'url(#bg)');
    $b   .= el('path', ['d' => blob($r, 400, 400, 330, 9, 0.08), 'fill' => '#ffffff', 'opacity' => '.6']);
    $petals = static function (int $n, float $len, float $wid, string $fill, float $off): string {
        $o = '';
        for ($i = 0; $i < $n; $i++) {
            $a  = $off + 360 * $i / $n;
            $o .= el('ellipse', ['cx' => 400, 'cy' => f(400 - $len / 2), 'rx' => $wid, 'ry' => f($len / 2), 'fill' => $fill, 'transform' => 'rotate(' . f($a) . ' 400 400)']);
        }

        return $o;
    };
    $b .= $petals(12, 300, 52.0, 'url(#p1)', 0) . $petals(12, 220, 44.0, 'url(#p2)', 15) . $petals(8, 140, 34.0, $c['300'], 0);
    $b .= circ(400, 400, 56, 'url(#cn)');
    for ($i = 0; $i < 10; $i++) {
        $a  = 2 * M_PI * $i / 10;
        $b .= circ(400 + 32 * cos($a), 400 + 32 * sin($a), 5, '#b45309', ['opacity' => '.6']);
    }
    $b .= sparkle(680, 130, 18, $c['500']) . sparkle(120, 680, 14, $c['400']);

    return [$defs, $b];
}

function sq_gold(Rng $r): array
{
    $c    = PAL['gold'];
    $defs = lin('bg', [[0, '#fef7e6'], [1, $c['100']]], 0, 0, 1, 1) . lin('cup', [[0, '#ffffff'], [1, '#efe7da']], 0, 0, 1, 0) . lin('cof', [[0, '#7c4a1e'], [1, '#4a2a0f']]);
    $b    = rr(0, 0, 800, 800, 0, 'url(#bg)') . circ(400, 420, 290, $c['200'], ['opacity' => '.55']);
    $b   .= el('ellipse', ['cx' => 400, 'cy' => 610, 'rx' => 250, 'ry' => 46, 'fill' => '#e9dcc6']) . el('ellipse', ['cx' => 400, 'cy' => 600, 'rx' => 250, 'ry' => 46, 'fill' => '#ffffff']);
    $b   .= el('ellipse', ['cx' => 400, 'cy' => 598, 'rx' => 150, 'ry' => 24, 'fill' => '#efe7da']);
    $b   .= el('path', ['d' => 'M545 400C640 390 650 520 548 520', 'stroke' => '#efe7da', 'stroke-width' => 30, 'fill' => 'none']);
    $b   .= el('path', ['d' => 'M230 380H570C570 500 520 600 400 600C280 600 230 500 230 380Z', 'fill' => 'url(#cup)']);
    $b   .= el('ellipse', ['cx' => 400, 'cy' => 380, 'rx' => 170, 'ry' => 36, 'fill' => '#ffffff']);
    $b   .= el('ellipse', ['cx' => 400, 'cy' => 384, 'rx' => 150, 'ry' => 26, 'fill' => 'url(#cof)']);
    $b   .= el('path', ['d' => 'M370 380Q400 360 430 380Q400 400 370 380Z', 'fill' => '#e8c9a0', 'opacity' => '.8']);
    $b   .= el('path', ['d' => 'M340 320C320 280 360 250 340 200M400 310C380 260 425 230 400 170M460 320C440 280 480 250 460 200', 'stroke' => '#ffffff', 'stroke-width' => 12, 'fill' => 'none', 'stroke-linecap' => 'round', 'opacity' => '.85']);
    $b   .= rr(280, 450, 240, 10, 5, $c['500'], ['opacity' => '.5']);
    $b   .= sparkle(650, 180, 16, $c['500']) . plus(150, 200, 12, $c['400'], 6);

    return [$defs, $b];
