// ---------------------------------------------------------------------------
// AVATARS (400×400) — friendly illustrated people, clearly not photographs.
// ---------------------------------------------------------------------------

/** @param array{bg:string,ring:string,skin:string,shade:string,hair:string,shirt:string,style:string,glasses?:bool,beard?:bool} $o */
function avatar(array $o): array
{
    $skin  = $o['skin'];
    $shade = $o['shade'];
    $hair  = $o['hair'];
    $defs  = lin('bg', [[0, $o['bg']], [1, $o['ring']]], 0, 0, 1, 1);
    $bg    = rr(0, 0, 400, 400, 0, 'url(#bg)') . circ(200, 214, 160, '#ffffff', ['opacity' => '.35']);
    $b     = '';

    $back  = '';
    $front = '';
    switch ($o['style']) {
        case 'short':
            $front = el('path', ['d' => 'M128 196C118 126 158 92 206 94C254 96 286 132 272 198C268 172 258 154 244 146C220 160 176 158 146 150C138 164 132 180 128 196Z', 'fill' => $hair]);
            break;
        case 'long':
            $back  = el('path', ['d' => 'M110 330C88 220 106 92 200 88C294 92 312 220 290 330C262 346 138 346 110 330Z', 'fill' => $hair]);
            $front = el('path', ['d' => 'M128 200C120 128 158 94 204 94C250 96 284 130 274 204C262 166 236 138 196 132C172 150 150 170 128 200Z', 'fill' => $hair]);
            break;
        case 'curly':
            $curls = '';
            for ($i = 0; $i < 13; $i++) {
                $a      = M_PI * (0.95 + 1.1 * $i / 12);
                $curls .= circ(200 + 92 * cos($a), 170 + 86 * sin($a), 34, $hair);
            }
            $back  = el('ellipse', ['cx' => 200, 'cy' => 160, 'rx' => 110, 'ry' => 96, 'fill' => $hair]) . $curls;
            $front = el('path', ['d' => 'M130 176C128 120 162 94 200 94C238 94 272 120 270 176C250 154 226 146 200 146C174 146 150 154 130 176Z', 'fill' => $hair]);
            break;
        case 'bun':
            $back  = circ(200, 82, 40, $hair);
            $front = el('path', ['d' => 'M128 198C120 128 158 98 202 98C248 98 282 128 272 198C262 160 236 132 200 128C164 132 138 160 128 198Z', 'fill' => $hair]);
            break;
        case 'bob':
            $back  = el('path', ['d' => 'M114 262C96 156 136 88 200 88C264 88 304 156 286 262C270 270 130 270 114 262Z', 'fill' => $hair]);
            $front = el('path', ['d' => 'M130 182C130 126 164 100 200 100C236 100 270 126 270 182C246 160 222 150 200 150C174 150 152 160 130 182Z', 'fill' => $hair]);
            break;
        case 'bald':
            $front = el('path', ['d' => 'M132 200C128 180 130 166 136 152C140 170 140 186 140 204ZM268 200C272 180 270 166 264 152C260 170 260 186 260 204Z', 'fill' => $hair]);
            break;
        case 'scarf':
            $back  = el('path', ['d' => 'M200 76C116 76 92 160 100 236C106 300 132 326 200 332C268 326 294 300 300 236C308 160 284 76 200 76Z', 'fill' => $hair]);
            $front = el('path', ['d' => 'M134 160C150 116 176 104 200 104C224 104 250 116 266 160C246 140 224 134 200 134C176 134 154 140 134 160Z', 'fill' => $hair])
                . el('path', ['d' => 'M146 128C168 112 232 112 254 128', 'stroke' => '#ffffff', 'stroke-opacity' => '.25', 'stroke-width' => 6, 'fill' => 'none', 'stroke-linecap' => 'round']);
            break;
        case 'pony':
            $back  = el('path', ['d' => 'M262 140C320 150 330 240 300 300C296 250 280 210 256 190Z', 'fill' => $hair]);
            $front = el('path', ['d' => 'M128 198C118 128 158 94 204 94C250 96 284 130 272 196C258 156 226 128 172 136C150 152 136 172 128 198Z', 'fill' => $hair]);
            break;
    }

    $shirt = $o['shirt'];
    $body  = el('path', ['d' => 'M58 400C58 330 112 290 200 290C288 290 342 330 342 400Z', 'fill' => $shirt]);
    if ($o['style'] === 'scarf') {
        // The scarf wraps the head and neck and drapes over the shoulders.
        $b .= $body;
        $b .= el('path', ['d' => 'M104 236C110 300 128 336 112 400H288C272 336 290 300 296 236Z', 'fill' => $hair]);
        $b .= $back;
        $b .= el('path', ['d' => 'M150 318Q200 350 250 318', 'stroke' => '#ffffff', 'stroke-opacity' => '.18', 'stroke-width' => 6, 'fill' => 'none', 'stroke-linecap' => 'round']);
    } else {
        $b .= $back . $body;
        $b .= rr(172, 226, 56, 82, 24, $shade);
        $b .= el('path', ['d' => 'M168 290Q200 336 232 290Z', 'fill' => $shade]);
        $b .= el('path', ['d' => 'M160 292Q200 344 240 292', 'stroke' => '#ffffff', 'stroke-opacity' => '.35', 'stroke-width' => 6, 'fill' => 'none']);
    }
    if (!in_array($o['style'], ['scarf', 'bob', 'long'], true)) {
        $b .= el('ellipse', ['cx' => 130, 'cy' => 192, 'rx' => 14, 'ry' => 19, 'fill' => $skin]) . el('ellipse', ['cx' => 270, 'cy' => 192, 'rx' => 14, 'ry' => 19, 'fill' => $skin]);
    }
    $b .= el('ellipse', ['cx' => 200, 'cy' => 182, 'rx' => 70, 'ry' => 80, 'fill' => $skin]);
    // Face.
    $b .= circ(160, 218, 13, '#fb7185', ['opacity' => '.22']) . circ(240, 218, 13, '#fb7185', ['opacity' => '.22']);
    $b .= el('ellipse', ['cx' => 174, 'cy' => 192, 'rx' => 7, 'ry' => 8.5, 'fill' => '#1f2937']) . el('ellipse', ['cx' => 226, 'cy' => 192, 'rx' => 7, 'ry' => 8.5, 'fill' => '#1f2937']);
    $b .= circ(176.5, 189, 2.4, '#ffffff') . circ(228.5, 189, 2.4, '#ffffff');
    $brow = $o['style'] === 'scarf' ? '#3b2a20' : $hair;
    $b .= el('path', ['d' => 'M160 170Q174 162 188 168M212 168Q226 162 240 170', 'stroke' => $brow, 'stroke-width' => 5, 'fill' => 'none', 'stroke-linecap' => 'round']);
    $b .= el('path', ['d' => 'M200 198Q207 212 197 216', 'stroke' => $shade, 'stroke-width' => 4, 'fill' => 'none', 'stroke-linecap' => 'round']);
    if (!empty($o['beard'])) {
        $b .= el('path', ['d' => 'M131 192C134 266 168 292 200 292C232 292 266 266 269 192C258 222 238 236 224 234Q200 222 176 234C162 236 142 222 131 192Z', 'fill' => $hair]);
        $b .= el('path', ['d' => 'M182 240Q200 252 218 240', 'stroke' => '#ffffff', 'stroke-width' => 5, 'fill' => 'none', 'stroke-linecap' => 'round', 'opacity' => '.9']);
    } else {
        $b .= el('path', ['d' => 'M180 228Q200 248 220 228Z', 'fill' => '#9f1239']) . el('path', ['d' => 'M184 229H216', 'stroke' => '#ffffff', 'stroke-width' => 3]);
    }
    $b .= $front;
    if (!empty($o['glasses'])) {
        $b .= el('g', ['fill' => '#ffffff', 'fill-opacity' => '.15', 'stroke' => '#1f2937', 'stroke-width' => 5],
            rr(148, 174, 52, 38, 14, '#ffffff') . rr(200 + 2, 174, 52, 38, 14, '#ffffff'));
        $b .= el('path', ['d' => 'M196 186Q201 182 206 186', 'stroke' => '#1f2937', 'stroke-width' => 5, 'fill' => 'none']);
    }

    // Frame the figure a little tighter so it reads well in small circular crops.
    return [$defs, $bg . el('g', ['transform' => 'translate(-30 -34.5) scale(1.15)'], $b)];
}

// ---------------------------------------------------------------------------
// LOGOS (600×200) — abstract marks + wordmark bars, NO text, transparent bg.
