function logoBars(float $x, string $ink, string $soft): string
{
    return rr($x, 74, 250, 30, 15, $ink) . rr($x, 118, 170, 14, 7, $soft);
}

function logo_1(Rng $r): array
{
    $c    = PAL['blue'];
    $defs = lin('m', [[0, $c['400']], [1, $c['700']]], 0, 0, 1, 1);
    $b    = rr(70, 40, 120, 120, 32, 'url(#m)') . sparkle(130, 100, 38, '#ffffff') . circ(158, 70, 7, '#ffffff', ['opacity' => '.7']);
    $b   .= logoBars(220, '#1e293b', '#94a3b8');

    return [$defs, $b];
}

function logo_2(Rng $r): array
{
    $c    = PAL['teal'];
    $defs = lin('m', [[0, $c['300']], [1, $c['700']]], 0, 0, 1, 1);
    $hex  = [];
    for ($i = 0; $i < 6; $i++) {
        $a     = M_PI / 6 + $i * M_PI / 3;
        $hex[] = f(130 + 64 * cos($a)) . ' ' . f(100 + 64 * sin($a));
    }
    $b  = el('polygon', ['points' => implode(' ', $hex), 'fill' => 'url(#m)', 'stroke' => 'url(#m)', 'stroke-width' => 10, 'stroke-linejoin' => 'round']);
    $b .= circ(130, 100, 24, '#ffffff') . circ(130, 100, 10, $c['600']);
    $b .= logoBars(220, '#134e4a', '#5eead4');

    return [$defs, $b];
}

function logo_3(Rng $r): array
{
    $c    = PAL['purple'];
    $defs = '';
    $b    = circ(130, 76, 38, '#fbbf24', ['opacity' => '.9']) . circ(109, 114, 38, $c['500'], ['opacity' => '.85']) . circ(151, 114, 38, $c['acc'], ['opacity' => '.85']);
    $b   .= logoBars(220, '#2e1065', '#c4b5fd');

    return [$defs, $b];
}

function logo_4(Rng $r): array
{
    $b  = el('path', ['d' => 'M70 150L130 50L190 150Z', 'fill' => 'none', 'stroke' => '#ffffff', 'stroke-width' => 14, 'stroke-linejoin' => 'round']);
    $b .= circ(130, 116, 18, '#ffffff');
    $b .= rr(220, 74, 250, 30, 15, '#ffffff') . rr(220, 118, 170, 14, 7, '#ffffff', ['opacity' => '.7']);

    return ['', $b];
}

