/** @return list<array{token:string,role:string,palette:string,w:int,h:int,tone:string,alt:string,fn:callable}> */
function catalogue(): array
{
    $list = [];
    $add  = static function (string $token, string $role, string $palette, int $w, int $h, string $tone, string $alt, callable $fn) use (&$list): void {
        $list[] = compact('token', 'role', 'palette', 'w', 'h', 'tone', 'alt', 'fn');
    };

    $heroes = [
        'blue'   => 'Dark blue abstract background with glowing gradients, fine flowing lines and layered waves',
        'purple' => 'Dark purple abstract background with a glowing pink-to-cyan aurora ribbon and stars',
        'teal'   => 'Dark teal abstract background with glowing concentric rings and orbiting dots',
        'sunset' => 'Dark retro sunset with a glowing striped sun over layered dunes',
        'forest' => 'Dark green layered mountain ridges in mist under a pale moon and stars',
        'slate'  => 'Dark slate tech background with a glowing perspective grid and floating glass panels',
        'rose'   => 'Dark rose abstract background with soft blurred pink and magenta shapes',
        'gold'   => 'Dark amber background with glowing gold bokeh, a light beam and fine arcs',
    ];
    foreach ($heroes as $p => $alt) {
        $add('hero-' . $p . '-1', 'hero', $p, 1600, 900, 'dark', $alt, 'hero_' . $p);
    }

    $bgs = [
        'slate'  => ['light', 'Light grey background with a subtle dot pattern fading towards the centre'],
        'blue'   => ['light', 'Very light blue background with a faint grid and soft glows'],
        'purple' => ['dark', 'Deep purple background with faint diagonal lines and a soft glow'],
        'teal'   => ['light', 'Very light mint background with thin flowing wave lines'],
        'rose'   => ['light', 'Very light pink background with soft blurred pastel blobs'],
        'forest' => ['dark', 'Deep green background with faint topographic contour lines'],
        'gold'   => ['light', 'Light cream background with a soft geometric tile pattern'],
        'sunset' => ['dark', 'Smooth dark plum-to-burnt-orange gradient with soft glows'],
    ];
    foreach ($bgs as $p => [$tone, $alt]) {
        $add('section-bg-' . $p . '-1', 'section-bg', $p, 1600, 900, $tone, $alt, 'bg_' . $p);
    }

    $cards = [
        'blue'   => 'Illustration of an analytics dashboard with bar, line and donut charts',
        'purple' => 'Illustration of a laptop and a phone showing a website, with a small plant',
        'teal'   => 'Illustration of a security shield with a check mark and lock badges',
        'sunset' => 'Illustration of a rocket launching through clouds',
        'forest' => 'Illustration of a green sprout with three leaves in a terracotta pot',
        'gold'   => 'Illustration of a glowing light bulb idea',
        'rose'   => 'Illustration of two interlocking rings with a heart, symbolising partnership',
        'slate'  => 'Illustration of a folded map with a dashed route and a red location pin',
    ];
    foreach ($cards as $p => $alt) {
        $add('card-' . $p . '-1', 'card', $p, 1200, 900, 'light', $alt, 'card_' . $p);
    }

    $squares = [
        'slate'  => ['light', 'Abstract composition of slate-grey circles, a square and arcs'],
        'blue'   => ['dark', 'Illustrated night sea with a full moon and layered blue waves'],
        'purple' => ['dark', 'Illustrated ringed planet in a purple starry sky'],
        'teal'   => ['dark', 'Geometric tile pattern of teal circles, arcs and triangles'],
        'sunset' => ['light', 'Illustrated sunset over layered pink and plum mountains'],
        'forest' => ['light', 'Illustrated potted plant with green leaves'],
        'rose'   => ['light', 'Illustrated pink flower with layered petals'],
        'gold'   => ['light', 'Illustrated cup of coffee with steam on a saucer'],
    ];
    foreach ($squares as $p => [$tone, $alt]) {
        $add('square-' . $p . '-1', 'square', $p, 800, 800, $tone, $alt, 'sq_' . $p);
    }

    $avatars = [
        ['blue', ['bg' => '#dbeafe', 'ring' => '#93c5fd', 'skin' => '#f6d3bd', 'shade' => '#e6b69b', 'hair' => '#3b2416', 'shirt' => '#2563eb', 'style' => 'short'], 'person with short dark-brown hair'],
        ['rose', ['bg' => '#ffe4e6', 'ring' => '#fda4af', 'skin' => '#8d5a3b', 'shade' => '#744528', 'hair' => '#1c120c', 'shirt' => '#e11d48', 'style' => 'curly'], 'person with curly black hair'],
        ['teal', ['bg' => '#ccfbf1', 'ring' => '#5eead4', 'skin' => '#f1c79f', 'shade' => '#dcaa7f', 'hair' => '#d69e4a', 'shirt' => '#0f766e', 'style' => 'long'], 'person with long blonde hair'],
        ['gold', ['bg' => '#fef3c7', 'ring' => '#fcd34d', 'skin' => '#c68642', 'shade' => '#a96d33', 'hair' => '#2b1a10', 'shirt' => '#334155', 'style' => 'bald', 'beard' => true, 'glasses' => true], 'person with a beard and glasses'],
        ['purple', ['bg' => '#ede9fe', 'ring' => '#c4b5fd', 'skin' => '#e0a878', 'shade' => '#c78c5e', 'hair' => '#7c2d12', 'shirt' => '#7c3aed', 'style' => 'bun'], 'person with auburn hair in a bun'],
        ['forest', ['bg' => '#dcfce7', 'ring' => '#86efac', 'skin' => '#5e3a24', 'shade' => '#4b2c19', 'hair' => '#0f766e', 'shirt' => '#facc15', 'style' => 'scarf'], 'person wearing a teal headscarf'],
        ['sunset', ['bg' => '#ffedd5', 'ring' => '#fdba74', 'skin' => '#f8d9c4', 'shade' => '#e8bca2', 'hair' => '#9ca3af', 'shirt' => '#c2410c', 'style' => 'bob', 'glasses' => true], 'person with a grey bob and glasses'],
        ['slate', ['bg' => '#e2e8f0', 'ring' => '#94a3b8', 'skin' => '#a86b45', 'shade' => '#8e5634', 'hair' => '#111827', 'shirt' => '#0ea5e9', 'style' => 'pony'], 'person with a dark ponytail'],
    ];
    foreach ($avatars as $i => [$p, $opts, $who]) {
        $bgName = ['blue' => 'light blue', 'rose' => 'pink', 'teal' => 'mint', 'gold' => 'pale yellow', 'purple' => 'lavender', 'forest' => 'light green', 'sunset' => 'peach', 'slate' => 'light grey'][$p];
        $add('avatar-' . ($i + 1), 'avatar', $p, 400, 400, 'light', 'Illustrated avatar of a smiling ' . $who . ' on a ' . $bgName . ' background', static fn (Rng $r) => avatar($opts));
    }

    $logos = [
        ['blue', 'light', 'Placeholder logo: blue rounded-square emblem with a sparkle and abstract wordmark bars (no text)', 'logo_1'],
        ['teal', 'light', 'Placeholder logo: teal hexagon emblem and abstract wordmark bars (no text)', 'logo_2'],
        ['purple', 'light', 'Placeholder logo: overlapping purple, pink and yellow circles with abstract wordmark bars (no text)', 'logo_3'],
        ['white', 'dark', 'Placeholder logo in white for dark backgrounds: triangle emblem and abstract wordmark bars (no text)', 'logo_4'],
    ];
    foreach ($logos as $i => [$p, $tone, $alt, $fn]) {
        $add('logo-' . ($i + 1), 'logo', $p, 600, 200, $tone, $alt, $fn);
    }

    return $list;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

function ratio(int $w, int $h): string
{
    $a = $w;
    $b = $h;
    while ($b !== 0) {
        [$a, $b] = [$b, $a % $b];
    }

    return ($w / $a) . ':' . ($h / $a);
}

$root   = dirname(__DIR__);
$outDir = $argv[1] ?? $root . '/wp-plugin/assets/images';
if (!is_dir($outDir) && !mkdir($outDir, 0777, true) && !is_dir($outDir)) {
    fwrite(STDERR, "Cannot create {$outDir}\n");
    exit(1);
}

$images = [];
$errors = [];
foreach (catalogue() as $n => $item) {
    $seed       = 1000 + $n * 7919;
    [$defs, $b] = ($item['fn'])(new Rng($seed));
    $svg        = svg($item['w'], $item['h'], $item['alt'], $defs, $b);
    $file       = $item['token'] . '.svg';

    // Self-checks mirror tests/ImagePackTest.php so a bad build fails here first.
    if (strlen($svg) > 61440) {
        $errors[] = "{$file} is " . strlen($svg) . ' bytes (> 60 KB)';
    }
    if (preg_match('#(href|src)="https?://#i', $svg) || preg_match('/on[a-z]+\s*=/i', $svg) || stripos($svg, '<script') !== false) {
        $errors[] = "{$file} contains a forbidden construct";
    }
    if (function_exists('simplexml_load_string')) {
        libxml_use_internal_errors(true);
        if (simplexml_load_string($svg) === false) {
            $errors[] = "{$file} is not well-formed XML";
        }
        libxml_clear_errors();
    }

    file_put_contents($outDir . '/' . $file, $svg);
    $images[] = [
        'token'   => $item['token'],
        'file'    => $file,
        'ratio'   => ratio($item['w'], $item['h']),
        'width'   => $item['w'],
        'height'  => $item['h'],
        'palette' => $item['palette'],
        'role'    => $item['role'],
        'tone'    => $item['tone'],
        'alt'     => $item['alt'],
    ];
}

$manifest = ['fallback' => 'square-slate-1', 'images' => $images];
file_put_contents($outDir . '/manifest.json', json_encode($manifest, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . "\n");

$readme = <<<TXT
JHMG AI Editor for Divi 5 - built-in image pack
================================================

Original artwork generated by a script in the plugin's development repository, © JHMG, released under GPL-2.0-or-later.

Every image in this folder is an original SVG illustration produced by a
deterministic generator script. None of it is a photograph and none of it is
taken from a third-party stock library. The files are served from this plugin's
own folder on your site; nothing is loaded from a remote host.

manifest.json lists every image with its token, role (hero, section-bg, card,
square, avatar, logo), aspect ratio, palette, tone (dark = use light text on it,
light = use dark text on it) and alt text. Page layouts reference images with
tokens such as {{aied:image:hero-blue-1}}, which the plugin resolves to the URL
of the matching file in this folder.

TXT;
file_put_contents($outDir . '/README.txt', $readme);

if ($errors !== []) {
    fwrite(STDERR, implode("\n", $errors) . "\n");
    exit(1);
}

echo 'Wrote ' . count($images) . " images + manifest.json + README.txt to {$outDir}\n";
